window.getOutthinkAnnotation = function(model, level, tier, seed) {
  var store = window.OUTTHINK_ANNOTATIONS && window.OUTTHINK_ANNOTATIONS.episodes;
  if (!store || model === null || model === undefined) {
    return null;
  }
  if (arguments.length === 1 && typeof model === "object") {
    var obj = model;
    model = obj.model;
    level = obj.level || obj.thinking_level;
    tier = obj.tier;
    seed = obj.seed;
  }
  if (arguments.length === 1 && typeof model === "string") {
    var raw = model.trim();
    if (store[raw]) {
      return store[raw];
    }
    if (raw.indexOf("|") !== -1) {
      var parts = raw.split("|");
      if (parts.length === 4) {
        model = parts[0];
        level = parts[1];
        tier = parts[2];
        seed = parts[3];
      }
    } else if (raw.indexOf("/") !== -1) {
      var sp = raw.split("/");
      if (sp.length === 4) {
        model = sp[0];
        level = sp[1];
        tier = sp[2];
        seed = sp[3];
      }
    }
  }
  var m = String(model || "").replace(/^gemini:/, "").trim();
  var lv = String(level || "").trim().toLowerCase();
  var tr = String(tier || "").trim().toLowerCase();
  var sd = String(seed !== undefined && seed !== null ? seed : "").trim();
  var key = m + "/" + lv + "/" + tr + "/" + sd;
  return store[key] || null;
};
